        let done = Arc::clone(&done_t2);
        thread::Builder::new()
            .name("t2".to_string())
            .spawn(move || worker(a, b, done))
            .unwrap()
    };

    // Main finishes only after both workers have finished (R6).
    t1.join().unwrap();
    t2.join().unwrap();

    // R9: print exactly this line and exit.
    println!(
        "DONE t1={} t2={}",
        done_t1.load(Ordering::SeqCst),
        done_t2.load(Ordering::SeqCst)
