    let a1 = Arc::clone(&a);
    let b1 = Arc::clone(&b);
    let h1 = thread::spawn(move || module1::t1(a1, b1));

    let a2 = Arc::clone(&a);
    let b2 = Arc::clone(&b);
    let h2 = thread::spawn(move || module2::t2(a2, b2));

    // R7/R8: wait for both tasks to finish, across both modules.
    h1.join().unwrap();
    h2.join().unwrap();

    // R10: print exactly this line and exit.
    println!("DONE done=1");
